#!/usr/bin/env python3
"""
Run from project root: python3 fix_build.py
"""
import base64, os, sys

if not os.path.exists("components"):
    print("ERROR: Run from project root"); sys.exit(1)

FILES = {
    "components/IssuanceEngine.tsx": "",
    "components/CertificateDisplay.tsx": "",
    "components/AssetDetailClient.tsx": "",
    "lib/auth.ts": "",
    "types/next-auth.d.ts": "",
    "tailwind.config.js": "",
    "next.config.js": "",
}

for path, enc in FILES.items():
    os.makedirs(os.path.dirname(path), exist_ok=True) if os.path.dirname(path) else None
    content = base64.b64decode(enc).decode("utf-8")
    open(path, "w", encoding="utf-8", newline="\n").write(content)
    print(f"FIXED  {path} ({len(content.splitlines())} lines)")

# Clean up old temp scripts
for f in ["fix_all.py","fix_final.py","fix_issuance.py","fix_engine.py"]:
    if os.path.exists(f): os.remove(f); print(f"REMOVED  {f}")

print("\nDone. Run: npm run build")
